WITH ranked AS MATERIALIZED (SELECT rowid,rank AS relevance FROM content_search WHERE content_search MATCH ?), scored AS (SELECT b.record_id,s.relevance,b.id AS block_id FROM ranked s JOIN content_blocks b INDEXED BY content_block_identity ON b.id=s.rowid), documents AS (SELECT record_id,min(relevance) AS relevance,block_id FROM scored GROUP BY record_id) SELECT d.record_id,d.relevance,d.block_id FROM documents d JOIN available_search_records r ON r.id=d.record_id LEFT JOIN workspace w ON w.record_id=r.id WHERE w.trashed IS NULL ORDER BY d.relevance,d.record_id LIMIT 101